:root{color-scheme:dark;--ground:#111713;--paper:#ecede0;--muted:#a4b0a5;--edge:#435047;--red:#e18a72;--gold:#ccb77e;--jade:#9fbba7;--console:#1b241e;--ease:cubic-bezier(.16,1,.3,1)}
*{box-sizing:border-box}
html,body,#root{width:100%;height:100%;margin:0;overflow:hidden}
body{background:var(--ground);color:var(--paper);font-family:"Microsoft YaHei","PingFang SC",sans-serif;letter-spacing:0}
button,input{font:inherit}button{color:inherit;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent}
button:disabled{opacity:.27;cursor:default}button:active:not(:disabled){filter:brightness(1.2)}
button:focus-visible,input:focus-visible,[tabindex]:focus-visible{outline:3px solid #edcc87;outline-offset:4px}
figure,p,h1,h2,h3{margin:0}svg{flex-shrink:0}img{display:block;max-width:100%;user-select:none;-webkit-user-drag:none}i{font-style:normal}
.exhibit{--console-height:104px;height:100dvh;display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;position:relative;isolation:isolate;overflow:hidden;user-select:none;-webkit-user-select:none;-webkit-app-region:no-drag}
.gallery-ground{position:absolute;inset:0;z-index:-1;pointer-events:none;overflow:hidden;background:#111b18;transition:background-color .7s}
.gallery-ground.ground-1{background:#111f20}
.gallery-ground.ground-2{background:#29191b}
.background-layer{position:absolute;inset:0;isolation:isolate}
.background-layer>.waves,.background-layer>.iridescence-container,.background-layer>.silk-container{position:absolute;inset:0;width:100%;height:100%}
.background-layer>.cloud-water-background{opacity:.82}
.background-layer>.mineral-background{opacity:.62}
.background-layer>.cinnabar-background{opacity:.62}
.background-quiet-zone{position:absolute;inset:0;background:linear-gradient(90deg,#111b18ed 0%,#111b18a6 23%,#111b1833 46%,#111b1833 65%,#111b18b3 80%,#111b18e6 100%)}
.ground-1 .background-quiet-zone{background:linear-gradient(90deg,#101d20d9 0%,#101d206b 28%,#101d2026 48%,#101d2033 68%,#101d20c4 100%)}
.ground-2 .background-quiet-zone{background:linear-gradient(90deg,#21171ce6 0%,#21171ca6 24%,#21171c26 45%,#21171c33 66%,#21171cb3 82%,#21171ce6 100%)}
.view-1 .touch-console{background:#14272bf7;border-top-color:#5c817480}
.view-2 .touch-console{background:#2a2021f7;border-top-color:#9b776780}
.ancient-ground{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.ground-2 .ancient-ground{opacity:.45}
.print-border{position:absolute;inset:22px 25px 105px;border:1px solid #b4a37825;pointer-events:none;z-index:-2}
.print-border:before,.print-border:after{content:"";position:absolute;width:96px;height:18px;border:1px solid #b4a37840}
.print-border:before{top:-4px;left:-4px;border-right:0;border-bottom:0}
.print-border:after{bottom:-4px;right:-4px;border-top:0;border-left:0}
.exhibit-stage{min-width:0;min-height:0;padding:42px 52px 24px}
.exhibit-scene{height:100%;display:grid;grid-template-columns:minmax(250px,.9fr) minmax(430px,1.7fr) minmax(280px,1fr);gap:36px;align-items:center}
.chapter-copy{min-width:0;min-height:0;max-height:100%;padding:8px 0;position:relative;z-index:2}
h1{font:400 59px/1.5 "Exhibit Serif",serif;white-space:nowrap;letter-spacing:0}
h1>p{margin:0}
.section-rule{display:flex;gap:14px;align-items:center;margin:14px 0 22px;color:var(--muted);font-size:16px}
.section-rule>i{height:2px;width:44px;background:var(--red)}
.chapter-stat{display:flex;align-items:baseline;gap:16px;margin:8px 0 24px}
.chapter-stat>span:first-child{font:400 88px/1.05 Georgia,serif;color:var(--gold);font-variant-numeric:tabular-nums}
.chapter-stat>span:last-child{font-size:16px;color:var(--muted)}
.selected-type{font:400 27px/1.4 "Exhibit Serif",serif;color:var(--red);margin:-8px 0 20px}
.type-chart{display:grid;gap:13px}
.type-bar{display:grid;grid-template-columns:102px minmax(0,1fr) 27px;align-items:center;gap:13px;color:#aab7ab;font-size:15px}
.type-bar>div{height:4px;background:#38453a}
.type-bar>div>i{height:100%;width:100%;display:block;transform-origin:left}
.type-bar b{font:400 19px Georgia,serif;text-align:right}
.type-bar.chosen{color:var(--paper)}
.chart-note{font-size:12px;line-height:1.8;color:#a4b2a4;margin-top:22px}
.artwork-stage{height:100%;min-width:0;min-height:0;position:relative;display:grid;grid-template-rows:minmax(0,1fr) auto 60px;gap:8px}
.artwork-holder{width:100%;height:100%;min-height:0}
.art-viewport{width:100%;height:100%;min-height:0;position:relative;overflow:hidden;cursor:grab;touch-action:none;overscroll-behavior:contain;outline-offset:-4px;-webkit-user-drag:none}
.art-viewport:active{cursor:grabbing}
.painting-plane{position:absolute;transform-origin:center}
.art-viewport[data-dragging=true] .painting-plane,.art-viewport[data-motion=wheel] .painting-plane{will-change:transform}
.painting-plane>img{width:100%;height:100%;object-fit:contain;box-shadow:0 15px 32px #0003;pointer-events:none}
.object-box{position:absolute;border:2px solid #5eeaffb3;box-shadow:0 0 0 1px #10242ce6;pointer-events:none;transition:border-color .2s;background:transparent}
.object-box>i{position:absolute;width:12px;height:12px;border-color:#5eeaff;border-style:solid;opacity:.8;filter:drop-shadow(0 1px 1px #05191f)}
.object-box>i:nth-child(1){top:-2px;left:-2px;border-width:2px 0 0 2px}
.object-box>i:nth-child(2){top:-2px;right:-2px;border-width:2px 2px 0 0}
.object-box>i:nth-child(3){bottom:-2px;left:-2px;border-width:0 0 2px 2px}
.object-box>i:nth-child(4){bottom:-2px;right:-2px;border-width:0 2px 2px 0}
.object-box.selected{border-color:#83f5ff;background:#45dced0a;box-shadow:0 0 0 1px #071e29,0 0 5px #59ebff80}
.object-box.selected>i{opacity:1;border-color:#c1fcff}
.object-traces{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}
.object-traces polyline{fill:none;stroke:#ffe4a8;stroke-width:2;vector-effect:non-scaling-stroke;stroke-linejoin:round;stroke-linecap:round;stroke-dasharray:6 5;animation:trace-flow 16s linear infinite}
.callout-layer{position:absolute;inset:0;pointer-events:none;overflow:hidden}
.callout path{fill:none;stroke:#e6ce9b;stroke-width:1;opacity:.65}
.callout circle{fill:#252c24;stroke:#e6ce9b;stroke-width:1.5}
.callout .point-center{fill:#e6ce9b;stroke:none}
.callout text{fill:#eee5ca;font-size:15px;font-family:"Microsoft YaHei",sans-serif;paint-order:stroke;stroke:#111b14;stroke-width:5px;stroke-linejoin:round}
.callout.selected path{stroke:#ffe1a2;opacity:1}
.callout.selected circle{stroke:#ffe1a2}
figcaption{display:flex;align-items:flex-start;gap:18px;justify-content:space-between;font-size:13px;color:#b7c2b3;line-height:1.6;padding:0 20px}
figcaption>span:first-child{display:flex;align-items:center;gap:10px;white-space:nowrap;color:var(--jade)}
figcaption i{height:12px;width:1px;background:var(--edge)}
figcaption>span:last-child{text-align:right;max-width:65%;overflow-wrap:anywhere}
.object-detail{min-width:0;min-height:0;max-height:100%;position:relative}
.object-name{display:flex;gap:16px;align-items:baseline;margin-bottom:25px}
.object-name>span{font:italic 20px Georgia,serif;color:var(--gold)}
.object-name h2{font:400 30px/1.6 "Exhibit Serif",serif}
.object-crop{height:250px;position:relative;overflow:hidden;background:#29332b;display:flex;align-items:center;justify-content:center}
.object-crop>img,.bw-layer>img{width:100%;height:100%;object-fit:contain}
.crop-corner{position:absolute;width:16px;height:16px;border:1px solid #baa776}
.corner-a{top:8px;left:8px;border-right:0;border-bottom:0}
.corner-b{bottom:8px;right:8px;border-top:0;border-left:0}
.object-feature{font-size:19px;line-height:1.9;color:#cad3c5;margin-top:24px}
.mini-spectrum{height:8px;display:flex;gap:4px;margin:24px 0 28px}
.mini-spectrum>i{height:100%}
.record-card{padding-top:22px;border-top:1px solid #62755a77}
.record-card>div{display:flex;justify-content:space-between;color:var(--gold);font-size:14px}
.record-card h3{font:400 23px/1.65 "Exhibit Serif",serif;margin-top:12px}
.record-card>p{font-size:14px;color:var(--muted);line-height:1.9;margin-top:16px}
.scene-1{grid-template-columns:minmax(265px,.93fr) minmax(400px,1.4fr) minmax(350px,1.2fr);gap:38px}
.color-copy h1{font-size:53px}
.color-wheel{width:176px;height:176px;margin:22px 0 28px;border-radius:50%;padding:26px;transform:rotate(-8deg)}
.color-wheel>div{height:100%;width:100%;background:#182119;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-direction:column;transform:rotate(8deg)}
.color-wheel strong{font:400 52px Georgia,serif;color:var(--paper)}
.color-wheel span{font-size:13px;color:var(--muted)}
.palette-bars{display:grid;gap:12px}
.palette-row{display:grid;grid-template-columns:14px 42px minmax(0,1fr) 48px;gap:12px;align-items:center;font-size:15px}
.palette-row>i{height:14px;width:14px;border:1px solid #ffffff28}
.palette-row>div{height:5px;background:#3c493b}
.palette-row>div>i{display:block;height:100%;width:100%;transform-origin:left}
.palette-row>b{text-align:right;font:400 19px Georgia,serif;color:var(--muted)}
.palette-row small{font-size:11px;margin-left:3px}
.compare-crop{height:310px}
.bw-layer{position:absolute;inset:0;background:#29332b;filter:grayscale(1)}
.compare-line{position:absolute;top:0;bottom:0;width:44px;transform:translateX(-50%);cursor:ew-resize;touch-action:none;z-index:2}
.compare-line:before{content:"";position:absolute;top:0;bottom:0;left:21px;width:2px;background:#fff8dc;box-shadow:0 0 0 1px #14292ccc}
.compare-line i{position:absolute;top:calc(50% - 22px);left:9px;display:grid;place-items:center;width:26px;height:44px;background:#f4e6bd;color:#182c30;border-radius:3px;border:1px solid #182c30;box-shadow:0 2px 6px #0006}
.compare-line:hover i,.compare-line:focus-visible i{background:#fff6d6}
.compare-line:focus-visible{outline-offset:-4px}
.crop-labels{display:flex;justify-content:space-between;font-size:12px;color:var(--muted);margin-top:11px}
.spectrum-strip{display:flex;gap:3px;height:38px;margin-top:25px}
.hex-palette{display:flex;flex-wrap:wrap;gap:12px 18px;margin:17px 0 28px}
.hex-palette>span{display:flex;align-items:center;gap:6px;font:12px monospace;color:var(--muted)}
.hex-palette i{width:9px;height:9px;border-radius:50%}
.meaning-copy h1{font-size:60px}
.meaning-text{font-size:21px;line-height:2;color:#c9d4c4;max-width:410px}
.meaning-network{max-width:400px;margin-top:18px}
.meaning-network>svg{width:100%;height:auto;display:block;overflow:visible}
.meaning-network circle{fill:#233128;stroke:#a99d705e;stroke-width:1}
.meaning-network circle:nth-of-type(2){fill:#352c25;stroke:#d19c7770}
.meaning-network circle:nth-of-type(3){fill:#2e3930;stroke:#a9bf9270}
.network-path{stroke:#6a7c625e;stroke-width:1.5;fill:none}
.network-flow{fill:none;stroke:#dfc187;stroke-width:2;stroke-dasharray:5 19;animation:trace-flow 8s linear infinite}
.meaning-network text{fill:#e4e5d4;text-anchor:middle;font-size:14px;font-family:"Exhibit Serif",serif}
.meaning-network .node-sub{fill:#9faa97;font-size:11px}
.wish-watermark{font:400 110px/1 "Exhibit Serif",serif;color:#4c5a4250;position:absolute;top:-100px;right:0;z-index:-1;white-space:nowrap}
.scene-2 .object-crop{height:220px}
.empty-state{grid-column:2/-1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24px;color:var(--muted)}
.empty-state h2{font:400 26px "Exhibit Serif",serif}
.touch-console{min-width:0;z-index:10;position:relative;background:#1b241ef2;border-top:1px solid #68775a77;box-shadow:0 -12px 45px #0c130c35}
.filter-drawer{overflow:hidden}
.filter-content{padding:7px 44px 10px;border-bottom:1px solid #596a4e70}
.filter-line{display:flex;gap:22px;align-items:center;min-width:0;min-height:57px}
.control-label{width:38px;flex-shrink:0;font-size:14px;color:#9ba994}
.filter-options{display:flex;align-items:center;gap:8px;overflow-x:auto;scrollbar-width:thin;scrollbar-color:#637956 transparent;min-width:0;flex:1;padding:4px}
.filter-choice{height:46px;display:flex;align-items:center;justify-content:center;gap:9px;white-space:nowrap;background:transparent;color:#b9c9b2;border:1px solid #586b50;border-radius:3px;padding:0 16px;font-size:15px;flex-shrink:0;transition:background .16s,border-color .16s}
.filter-choice>i{height:12px;width:5px}
.filter-choice .color-dot{width:20px;height:20px;border-radius:50%;border:1px solid #ffffff30}
.filter-choice>small{font:400 15px Georgia,serif;color:#9fae96}
.filter-choice.active{background:#c1cdb0;border-color:#c1cdb0;color:#172818}
.filter-choice.active small{color:#314632}
.group-options{flex:0 1 auto}
.group-line .filter-choice{border:0;height:42px;background:transparent;color:#aebfa7;padding:0 17px}
.group-line .filter-choice.active{background:#384d35;color:#e6edda}
.sample-count{margin-left:auto;white-space:nowrap;font-size:13px;color:#9eaf97}
.comparison-control{display:flex;align-items:center;gap:18px;width:430px;color:var(--muted);font-size:14px}
.comparison-control>input{flex:1;min-width:80px}
.palette-total{margin-left:auto;color:var(--muted);font-size:14px}
.palette-total strong{font:400 22px Georgia,serif;color:var(--gold);margin-right:8px}
.artwork-meta-row figcaption .title-evidence{display:block;font-size:12px;line-height:1.5;color:var(--muted);font-weight:400;margin-top:3px}
.meaning-key{font-size:15px;color:#afc0a4;gap:18px}
.meaning-key>.control-label{margin-right:4px}
.meaning-key>svg{color:#74896c}
.console-main{height:var(--console-height);display:flex;align-items:center;gap:21px;padding:0 44px}
.chapter-dock{width:240px;height:88px;position:relative;flex-shrink:0}
.exhibit-dock.dock{background:none!important;box-shadow:none!important;backdrop-filter:none;border-radius:0;bottom:6px}
.exhibit-dock .dock-face{background:#2a3b2c;color:#bfcfb7;box-shadow:none;border-radius:3px!important}
.exhibit-dock .chapter-active .dock-face{background:var(--red);color:#182619}
.exhibit-dock .chapter-0.chapter-active .dock-face{background:#c87560;color:#1d241b;border-color:#f1c397}
.exhibit-dock .chapter-1.chapter-active .dock-face{background:#668da0;color:#101f22;border-color:#b9d7d4}
.exhibit-dock .chapter-2.chapter-active .dock-face{background:#b56d63;color:#29191b;border-color:#f0c08e}
.chapter-face{height:100%;width:100%;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:3px}
.chapter-face>span{font-size:17px;line-height:1.4}
.icon-button{width:48px;height:50px;flex-shrink:0;border:1px solid #5b6e51;background:transparent;border-radius:3px;display:flex;align-items:center;justify-content:center;color:#c2d0b8}
.icon-button.active{background:#3a5038;border-color:#81956a;color:#e0d9a7}
.map-toggle{display:flex;align-items:center;gap:10px;border:0;border-right:1px solid #4c6045;padding:0 21px 0 0;background:none;flex-shrink:0;height:54px;font-size:16px;color:#bacbb1}
.map-toggle.active{color:var(--gold)}
.map-toggle>svg:last-child{color:#829978}
.browse-control{display:flex;align-items:center;gap:12px;flex:1;min-width:0}
.browse-control .icon-button{border:0;width:36px}
.thumbnail-rail{display:flex;align-items:center;gap:9px;flex:1;min-width:0;height:86px;overflow-x:auto;overflow-y:hidden;scrollbar-width:none;overscroll-behavior-x:contain;touch-action:pan-x;padding:5px 4px;position:relative}
.thumbnail-rail::-webkit-scrollbar{display:none}
.thumbnail{width:58px;height:74px;flex:0 0 58px;display:grid;grid-template-rows:minmax(0,1fr) 17px;gap:3px;background:#101b17;border:1px solid #53684e;border-radius:3px;padding:4px;color:#a9b8a0;transition:border-color .18s,background-color .18s}
.thumbnail>img{height:100%;width:100%;object-fit:contain;pointer-events:none}
.thumbnail>span{font:12px/17px Georgia,serif;text-align:center}
.thumbnail.active{border:2px solid var(--red);background:#403a2b;padding:3px;color:#f2dfbd}
.thumbnail:hover{border-color:#d7bf8a}
.thumbnail:focus-visible{outline-offset:-3px}
.thumbnail-count{display:flex;flex-direction:column;align-items:center;gap:4px;flex-shrink:0;min-width:30px;font:19px/1 Georgia,serif;font-variant-numeric:tabular-nums;color:var(--paper)}
.thumbnail-count>i{font-size:12px;color:#a2b296}
.console-main>.drawer-toggle{width:72px;height:72px;background:#354b32;border-color:#9aad81}
input[type=range]{display:block;appearance:none;-webkit-appearance:none;min-width:0;width:100%;height:46px;min-height:46px;background:transparent;cursor:ew-resize;touch-action:none;margin:0}
input[type=range]::-webkit-slider-runnable-track{height:4px;background:linear-gradient(to right,var(--red) 0 var(--fill),#596f50 var(--fill) 100%)}
input[type=range]::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:30px;height:30px;margin-top:-13px;border-radius:50%;border:5px solid #33452e;background:#e3d2a1;box-shadow:0 0 0 1px #a8b28a}
input[type=range]::-moz-range-track{height:4px;background:#596f50}
input[type=range]::-moz-range-thumb{width:22px;height:22px;background:#e3d2a1;border-radius:50%;border:4px solid #33452e}
.artwork-tools{display:flex;align-items:center;justify-content:center;gap:10px;min-width:0;height:60px}
.zoom-controls{display:flex;align-items:center;gap:7px;color:#9eae92;font-size:13px}
.zoom-controls>.icon-button{border:0;width:38px}
.zoom-controls>span{margin-right:3px}
.zoom-slider{width:105px;position:relative;padding-top:14px}
.zoom-slider>span{position:absolute;top:0;left:0;right:0;text-align:center;color:#b4c3a9;font:13px Georgia,serif}
.mark-toggle{margin-left:2px}
.map-sheet{position:absolute;bottom:var(--console-height);left:50%;width:min(920px,calc(100% - 60px));transform:translateX(-50%);background:#18251d;border:1px solid #768b60;box-shadow:0 -20px 80px #0008;z-index:20;padding:18px 28px 12px}
.map-intro{display:flex;gap:20px;align-items:center}
