.map-all.active{background:#3f5938;color:#ece9c7}
.map-geography{width:700px;max-width:100%;aspect-ratio:700/440;position:relative;margin:0 auto}
.map-geography>svg{width:100%;height:100%;display:block;overflow:visible}
.province{fill:#263c2c;stroke:#69805d;stroke-width:.55;vector-effect:non-scaling-stroke}
.province.has-records{fill:#4b6040;stroke:#b5b17b;cursor:pointer}
.province.selected{fill:#ba7056;stroke:#e5b582;stroke-width:1.5}
.map-origin>path{fill:none;stroke:#d1b57a;stroke-width:.7}
.map-origin>circle{fill:#d0b37a;stroke:#18291c;stroke-width:1}
.map-origin .map-origin-ring{fill:none;stroke:#d0b37a;stroke-width:.6;opacity:.45}
.map-origin.selected>circle{fill:#f2d9a3}
.map-place{position:absolute;transform:translate(-50%,-50%);display:flex;gap:6px;align-items:center;justify-content:center;min-width:96px;height:48px;border:0;background:#18251deb;border-radius:3px;color:#d8dfc2;padding:4px 7px;white-space:nowrap}
