.map-place>span{font:12px Georgia,serif;color:#bdae7b}
.map-place.active{background:#744c38;color:#fff0cc}
.map-credit{font-size:10px;color:#8ba081;display:block;text-align:right}
.chapter-track{position:absolute;left:6px;bottom:1px;width:214px;height:2px;background:#8b9d7733;pointer-events:none}
.chapter-track>i{display:block;width:62px;height:2px;background:var(--red);box-shadow:0 0 9px #e18a7240}
.icon-button,.object-choice,.map-toggle{transition:transform .18s var(--ease),background-color .18s,border-color .18s,color .18s}
.icon-button:active:not(:disabled),.object-choice:active:not(:disabled){transform:scale(.89)}
.map-toggle:active{transform:translateY(2px)}
.filter-choice{position:relative;transition:transform .18s var(--ease),background-color .22s,border-color .18s,color .18s}
.filter-choice:active:not(:disabled){transform:scale(.95)}
.filter-choice.active:after{content:"";position:absolute;bottom:3px;left:22%;right:22%;height:2px;background:currentColor;opacity:.35;transform-origin:left;animation:selection-ink .34s var(--ease) both}
.chapter-face{transition:transform .24s var(--ease)}
.dock-item:active .chapter-face{transform:scale(.87)}
.chapter-active .chapter-face>svg{animation:chapter-seal .42s var(--ease) both}
.chapter-copy{animation:copy-arrive .46s var(--ease) both}
.object-detail{animation:detail-arrive .54s var(--ease) both}
.section-rule>i{transform-origin:left;animation:selection-ink .6s var(--ease) both}
.callout.selected path{stroke-dasharray:1000;animation:leader-arrive .65s var(--ease) both}
.callout.selected>circle:first-of-type{animation:anchor-breathe 2.8s ease-in-out infinite}
.object-box.selected>i{animation:corner-arrive .42s var(--ease) both}
.color-wheel{animation:color-arrive .75s var(--ease) both}
.meaning-network circle{animation:node-arrive .5s var(--ease) both;transform-box:fill-box;transform-origin:center}
.meaning-network circle:nth-of-type(2){animation-delay:.09s}
.meaning-network circle:nth-of-type(3){animation-delay:.18s}
.filter-content{animation:drawer-arrive .36s var(--ease) both}
input[type=range]::-webkit-slider-thumb{transition:transform .16s var(--ease),box-shadow .16s}
input[type=range]:active::-webkit-slider-thumb{transform:scale(1.17);box-shadow:0 0 0 4px #e3d2a126}
@keyframes selection-ink{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes chapter-seal{from{transform:translateY(4px) rotate(-12deg)}to{transform:translateY(0) rotate(0)}}
@keyframes copy-arrive{from{transform:translateX(-18px);opacity:.35}to{transform:translateX(0);opacity:1}}
@keyframes detail-arrive{from{transform:translateX(22px);opacity:.4}to{transform:translateX(0);opacity:1}}
@keyframes leader-arrive{from{stroke-dashoffset:1000;opacity:.15}to{stroke-dashoffset:0;opacity:1}}
@keyframes anchor-breathe{0%,100%{stroke-opacity:.55;fill-opacity:.6}50%{stroke-opacity:1;fill-opacity:1}}
@keyframes corner-arrive{from{transform:scale(.65);opacity:.25}to{transform:scale(1);opacity:1}}
@keyframes color-arrive{from{transform:rotate(-65deg);opacity:.5}to{transform:rotate(-8deg);opacity:1}}
@keyframes node-arrive{from{transform:scale(.78);opacity:.3}to{transform:scale(1);opacity:1}}
@keyframes drawer-arrive{from{transform:translateY(12px);opacity:.4}to{transform:translateY(0);opacity:1}}
@keyframes trace-flow{to{stroke-dashoffset:-240}}
