/* Clip only the overscanned optics, not the mobile drawing tools above the console. */
.exhibit .touch-console{background:var(--glass-solid);backdrop-filter:none;-webkit-backdrop-filter:none;border-top:1px solid var(--glass-edge);box-shadow:none}
.liquid-filter{position:absolute;width:0;height:0;pointer-events:none}
.console-glass{display:none;position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:-1}
.liquid-backdrop{position:absolute;inset:-14px;pointer-events:none}
@supports ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){
  .exhibit .touch-console{background:transparent;isolation:isolate}
  .console-glass{display:block}
  .liquid-backdrop{background:var(--console-tint);backdrop-filter:blur(6px) saturate(115%);-webkit-backdrop-filter:blur(6px) saturate(115%)}
  @media(max-width:900px){.exhibit .flower-console-host{background:var(--console-tint);backdrop-filter:blur(6px) saturate(115%);-webkit-backdrop-filter:blur(6px) saturate(115%)}}
}

